import asyncio
import aiohttp
import logging
import math
import os
import platform

from contextlib import contextmanager
from time import perf_counter
from smtplib import SMTP
from email import header
from email.mime import text, multipart
from socket import socket, AF_INET, SOCK_DGRAM
from typing import Optional, List, Tuple, Any


from taf.ul.telemetry import settings

logger = logging.getLogger(__name__)


def _get_robot_context() -> Optional[object]:
    """
    This function attempts to import the EXECUTION_CONTEXTS from the robot.running.context module and return the current
    execution context. If the import or access fails, it catches the exception and returns None.

    Returns:
        EXECUTION_CONTEXTS.current: The current execution context if the import and access are successful.
        None: If any exception occurs during the import or access of EXECUTION_CONTEXTS.
    """
    try:
        from robot.running.context import EXECUTION_CONTEXTS
        return EXECUTION_CONTEXTS.current
    except Exception:
        pass
    return None


def is_dry_run() -> bool:
    """
    Function is responsible for checking if the current execution context is a robot dry run.
    If it is, it returns True, otherwise it returns False.

    Returns:
        True: If the current execution context is a dry run.
        False: If the current execution context is not a dry run or if any exception occurs.
    """
    try:
        current_context = _get_robot_context()
        if current_context.dry_run:
            logger.debug("Dry run detected")
            return True
    except Exception:
        pass
    return False


async def _check_host(host: str) -> Tuple[str, float]:
    """
    Function is responsible for checking the reachability of a given host by sending a GET request to it.
    It returns the host and the time it took to get a response.

    Args:
        host (str): The host to check.

    Returns:
        tuple: The host and the time it took to get a response. If any exception occurs, it returns the host and math.inf.
    """
    url = f"http://{host}:{settings.HEALTH_CHECK_PORT}"
    try:
        async with aiohttp.ClientSession() as session:
            t1 = perf_counter()
            async with session.get(url, timeout=settings.HEALTH_CHECK_CONNECTION_TIMEOUT) as response:
                logger.debug("Discovery - host %s returned %s", host, response.status)
                if response.status == 200:
                    return host, perf_counter() - t1
                else:
                    return host, math.inf
    except Exception as exc:
        logger.debug("Discovery - host %s errored with: (%s):%s", host, type(exc), exc)
        return host, math.inf


def check_host(host: str) -> Tuple[str, float]:
    return asyncio.run(_check_host(host))


async def _service_discovery(hosts: List[str]) -> str:
    selected_host = None

    tasks = [_check_host(host) for host in hosts]

    for future in asyncio.as_completed(tasks):
        try:
            current_host, elapsed = await future
            logger.debug("Discovery results for: %s, took %f", current_host, elapsed)
            if math.isfinite(elapsed):
                selected_host = current_host
                break
        except Exception:
            pass

    if selected_host:
        logger.debug("Picked host: %s", selected_host)
        settings._NOOP = False
        return selected_host
    settings._NOOP = True
    logger.warning("No host responded in time - telemetry will be disabled")
    return settings.LOCALHOST


def service_discovery(hosts: List[str]) -> str:
    """
    Function is responsible for performing service discovery by checking the reachability of a list of hosts.
    It returns the first host that responds successfully.

    Args:
        hosts (list): The list of hosts to check.

    Returns:
        str: The first host that responds successfully. If no host responds successfully, it returns 'localhost'.
    """
    return asyncio.run(_service_discovery(hosts))


def set_telemetry_host() -> None:
    """
    Function is responsible for setting the telemetry host. It performs service discovery if the host is not already
    set via an environment variable TELEMETRY_HOST or it is unreachable. If telemetry is explicitly disabled or
    in robot dry run, it disables telemetry. If no telemetry host is found, it disables telemetry.
    """
    # disable telemetry if explicitly disabled or in dry run or if hard switch is set
    if settings.TELEMETRY_DISABLED or is_dry_run() or check_telemetry_hard_switch():
        settings._NOOP = True
        logger.warning("Telemetry is DISABLED")
        return
    # check if host is already set via env var
    if settings._HOST and math.isinf(check_host(settings._HOST)[1]):
        logger.warning("TELEMETRY_HOST set via env var did not respond in time - will look for other hosts.")
        settings._HOST = None

    # check if host is not already set, perform service discovery
    if not settings._HOST:
        logger.debug("Checking available telemetry hosts - starting discovery")
        _HOST = service_discovery(settings.KNOWN_PROXIES)
        if _HOST != settings.LOCALHOST:
            logger.debug("Setting env var TELEMETRY_HOST to %s", _HOST)
            os.environ["TELEMETRY_HOST"] = _HOST
            settings._HOST = _HOST
        else:
            logger.warning("No telemetry host found - telemetry will be disabled")
            settings._NOOP = True
            logger.debug("Discovery finished unsuccessfully")
            logger.warning("Sending email")
            send_email_host_reachability_error()
            return
        logger.debug("Discovery finished successfully")

    settings._GRPC_ENDPOINT = f"http://{settings._HOST}:{settings._PORT_GRPC}"
    settings._HTTP_ENDPOINT = f"http://{settings._HOST}:{settings._PORT_HTTP}"
    settings._PROXY_ENDPOINT = f"http://{settings._HOST}:{settings._PORT_PROXY}"


def setup_exporters(create=True) -> Tuple[Any, Any, Any]:
    """
    Function is responsible for setting up exporters.

    Returns:
        tuple: metric exporter, trace exporter, log exporter.
    """
    if settings._TELEMETRY_EXPORTER == "grpc":
        from opentelemetry.exporter.otlp.proto.grpc.metric_exporter import OTLPMetricExporter
        from opentelemetry.exporter.otlp.proto.grpc.trace_exporter import OTLPSpanExporter
        from opentelemetry.exporter.otlp.proto.grpc._log_exporter import OTLPLogExporter

        metrics_ep = settings._GRPC_ENDPOINT
        traces_ep = settings._GRPC_ENDPOINT
        logs_ep = settings._GRPC_ENDPOINT
    else:
        from opentelemetry.exporter.otlp.proto.http.metric_exporter import OTLPMetricExporter
        from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter
        from opentelemetry.exporter.otlp.proto.http._log_exporter import OTLPLogExporter

        metrics_ep = f'{settings._HTTP_ENDPOINT}/v1/metrics'
        traces_ep = f'{settings._HTTP_ENDPOINT}/v1/traces'
        logs_ep = f'{settings._HTTP_ENDPOINT}/v1/logs'
    if create:
        return (OTLPMetricExporter(endpoint=metrics_ep),
                OTLPSpanExporter(endpoint=traces_ep),
                OTLPLogExporter(endpoint=logs_ep))


def send_email(sender: str, recipient: str, subject: str, message: str) -> None:
    """
    Function is responsible for sending an email with the given parameters.

    Args:
        sender (str): The sender of the email.
        recipient (str): The recipient of the email.
        subject (str): The subject of the email.
        message (str): The message of the email.
    """
    if is_dry_run() or settings.DISABLE_EMAILS or check_telemetry_hard_switch():
        return
    mail = multipart.MIMEMultipart()
    mail["From"] = sender
    mail["To"] = recipient
    mail["Subject"] = header.Header(subject).encode()
    mail.attach(text.MIMEText(message, "plain", "utf-8"))

    smtp = SMTP(timeout=3)
    try:
        smtp.connect(host=settings.MAIL_RELAY, port=25)
        smtp.sendmail(mail["From"], mail["To"], mail.as_string())
    except Exception as exp:
        logger.debug("Failed to send email: {}".format(exp))
    finally:
        try:
            smtp.quit()
        except Exception:
            pass


def send_email_import_error(error: str) -> None:
    """
    Function is responsible for sending an email about the failure to import opentelemetry.
    """
    msg = f"Host: {get_host_name()}\nHost IP: {get_host()}\nError: {error}"
    send_email(sender=settings.TELEMETRY_SENDER, recipient=settings.TELEMETRY_CONTACT, subject="Telemetry import error",
               message=msg)


def send_email_host_reachability_error() -> None:
    """
    Function is responsible for sending an email about the failure to reach the host.
    """
    msg = f"Host: {get_host_name()}\nHost IP: {get_host()}\nError: Could not reach telemetry host"
    send_email(sender=settings.TELEMETRY_SENDER, recipient=settings.TELEMETRY_CONTACT,
               subject="Telemetry host reachability error", message=msg)


def get_host() -> str:
    """
    Function is responsible for getting the host's IP address by creating a UDP connection to a public DNS
    server (8.8.8.8) and reading the socket's name. If any exception occurs, it returns 'localhost'.

    Returns:
        str: The host's IP address. If any exception occurs, it returns 'localhost'.
    """
    s = socket(AF_INET, SOCK_DGRAM)
    try:
        s.connect(('8.8.8.8', 80))
        return s.getsockname()[0]
    except Exception as exp:
        logger.debug("Failed to get host: {}".format(exp))
        return 'localhost'
    finally:
        s.close()


def get_host_name() -> str:
    """
    Function is responsible for getting the host's name using the platform module.
    Returns:
        str: The host's name.
    """
    return platform.node()


def check_telemetry_hard_switch() -> bool:
    """
    Function is responsible for checking if the hard switch file exists.
    Returns:
         bool: True if the file exists, False otherwise.
    """
    return settings.TELEMETRY_HARD_SWITCH_FILE.is_file()


@contextmanager
def disable_logging(logger_name):
    """
    Context manager to disable logging for a specific logger.
    """
    _logger = logging.getLogger(logger_name)
    _logger.disabled = True
    yield
    _logger.disabled = False
